			function onBtnSearchSearch2( /* cpr.events.CUIEvent */ e) {
			    /** 
			     * @type udc.com.comBtnSearch
			     */
			    var btnSearch = e.control;
			    
			    var filterStr = "";
			    
			    var dmSearch = app.lookup("dmSearch");
			    if (dmSearch.getValue("EXPORT_TITLE") != null && dmSearch.getValue("EXPORT_TITLE") != "") {
			        filterStr = "EXPORT_TITLE *= '" + dmSearch.getValue("EXPORT_TITLE") + "'";
			    }
			    if (dmSearch.getValue("MENU_URL") != null && dmSearch.getValue("MENU_URL") != "") {
			        if (filterStr == "") {
			            filterStr = "MENU_URL *= '" + dmSearch.getValue("MENU_URL") + "'";
			        } else {
			            filterStr += " and MENU_URL *= '" + dmSearch.getValue("MENU_URL") + "'";
			        }
			    }
			    if (dmSearch.getValue("IS_PERSONAL_INFO") != null && dmSearch.getValue("IS_PERSONAL_INFO") != "") {
			        if (filterStr == "") {
			            filterStr = "IS_PERSONAL_INFO == '" + dmSearch.getValue("IS_PERSONAL_INFO") + "'";
			        } else {
			            filterStr += " and IS_PERSONAL_INFO == '" + dmSearch.getValue("IS_PERSONAL_INFO") + "'";
			        }
			    }
			    if (dmSearch.getValue("MENU_NM") != null && dmSearch.getValue("MENU_NM") != "") {
			        if (filterStr == "") {
			            filterStr = "MENU_NM *= '" + dmSearch.getValue("MENU_NM") + "'";
			        } else {
			            filterStr += " and MENU_NM *= '" + dmSearch.getValue("MENU_NM") + "'";
			        }
			    }
			    if (dmSearch.getValue("ROOT_MENU_NM") != null && dmSearch.getValue("ROOT_MENU_NM") != "") {
			        if (filterStr == "") {
			            filterStr = "ROOT_MENU_NM *= '" + dmSearch.getValue("ROOT_MENU_NM") + "'";
			        } else {
			            filterStr += " and ROOT_MENU_NM *= '" + dmSearch.getValue("ROOT_MENU_NM") + "'";
			        }
			    }

			    //console.log("filterStr", filterStr);
			    
			    var dsList = app.lookup("dsList");
			    if (!ValueUtil.isNull(filterStr)) {
			        dsList.clearFilter();
			        dsList.setFilter(filterStr);
			    } else {
			        dsList.clearFilter();
			    }
			    
			}

